program='''from collections import Counter, deque

def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    bg=Counter(v for row in g for v in row).most_common(1)[0][0]
    seen=set()
    # Mark the background connected to the boundary.
    q=deque()
    for r in range(h):
        for c in (0,w-1):
            if g[r][c]==bg and (r,c) not in seen:
                seen.add((r,c)); q.append((r,c))
    for c in range(w):
        for r in (0,h-1):
            if g[r][c]==bg and (r,c) not in seen:
                seen.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0<=nr<h and 0<=nc<w and g[nr][nc]==bg and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    # Recolor enclosed background pockets: odd-sided pockets use 7, even-sided use 2.
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bg or (r,c) in seen:
                continue
            pocket=[]; q=deque([(r,c)]); seen.add((r,c))
            while q:
                rr,cc=q.popleft(); pocket.append((rr,cc))
                for nr,nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0<=nr<h and 0<=nc<w and g[nr][nc]==bg and (nr,nc) not in seen:
                        seen.add((nr,nc)); q.append((nr,nc))
            rows=[x for x,y in pocket]; cols=[y for x,y in pocket]
            height=max(rows)-min(rows)+1; width=max(cols)-min(cols)+1
            color=7 if height%2 and width%2 else 2
            for rr,cc in pocket:
                g[rr][cc]=color
    return g
'''
